class Solution {
    public int clumsy(int n){
        Deque<Integer> stack=new ArrayDeque<>();
        stack.push(n);
        int operation=0;
        for(int value=n-1;value>=1;value--,operation++){
            if(operation%4==0)stack.push(stack.pop()*value);
            else if(operation%4==1)stack.push(stack.pop()/value);
            else if(operation%4==2)stack.push(value);
            else stack.push(-value);
        }
        int answer=0;
        for(int value:stack)answer+=value;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun clumsy(n:Int):Int{
        val stack=java.util.ArrayDeque<Int>();
        stack.push(n);
        var operation=0;
        for(value in n-1 downTo 1){
            when(operation%4){
                0->stack.push(stack.pop()*value);
                1->stack.push(stack.pop()/value);
                2->stack.push(value);
                else->stack.push(-value)
            };
            operation++
        };
        return stack.sum()
    }
}

